AWT.zones = [{"id":"alps","name":"The Alps","kind":"mountain-high","note":"Passes such as the Alpis Graia (Little St Bernard) were deep in snow from late autumn to spring; Ammianus (15.10) describes travellers roped together on the ice.","ring":[[5.8,44.3],[7.3,44.1],[7.5,44.6],[7.2,45.3],[7.9,45.7],[9,45.9],[10.5,45.8],[12,46],[13.5,46.1],[14.5,46.3],[15.8,46.8],[15.5,47.6],[13,47.8],[10.5,47.6],[9.5,47.5],[8.5,47],[7,46.6],[6.2,46.3],[5.7,45.6]]},{"id":"armenia_hl","name":"Armenian highlands","kind":"mountain-high","note":"Xenophon's Ten Thousand lost men to deep snow and frostbite here in the winter of 401–400 BC (Anabasis 4.4–5).","ring":[[37.5,39],[39,40.6],[41.5,40.9],[44,40.6],[46.5,39.5],[45,38.3],[43,37.8],[41,38.3],[39,38.3]]},{"id":"zagros","name":"Zagros mountains","kind":"mountain-high","note":"The road up to Ecbatana and the Persian Gates crossed passes over 2,000 m; Alexander forced the snowy Persian Gates in winter 330 BC (Arrian 3.18).","ring":[[45,35.8],[46.5,35.2],[47.5,34],[49,32.5],[51.5,30.5],[53,29.5],[54,30.5],[52,32],[50,33.8],[48.5,35.5],[46.5,36.8]]},{"id":"caucasus","name":"Caucasus","kind":"mountain-high","note":"A wall of mountains crossed only by a few passes such as the Caspian Gates (Darial).","ring":[[37.5,44.5],[41,43.8],[44,43.2],[47,42.3],[49,41.3],[48,40.8],[45,41.8],[42,42.5],[39.5,43.3],[37.5,44]]},{"id":"pyrenees","name":"Pyrenees","kind":"mountain","note":"The Via Domitia crossed at the low eastern pass (Summum Pyrenaeum), usually open but stormy in winter.","ring":[[-1.8,43.2],[0,42.6],[2,42.3],[3.1,42.4],[3,42.7],[1.5,42.9],[-0.5,43.2],[-1.5,43.4]]},{"id":"apennines","name":"Apennines","kind":"mountain","note":"The spine of Italy; the Via Flaminia climbs over it to the Adriatic and the Via Appia crosses it near Beneventum.","ring":[[8.7,44.7],[10.5,44],[12,43.4],[13,42.6],[14,41.8],[15.5,40.8],[16.2,39.8],[16.4,39],[16,38.9],[15.4,40],[14.6,41],[13.6,41.6],[12.8,42.2],[11.8,43],[10.8,43.8],[9.4,44.5]]},{"id":"dinarides","name":"Dinaric Alps & Pindus","kind":"mountain","note":"Rugged limestone mountains behind the Adriatic coast; the Via Egnatia crosses them by the Candavian range.","ring":[[14,45.6],[16,44.8],[18,43.9],[19.8,42.8],[20.6,42],[21,41],[21.4,40],[21.6,39],[21,38.8],[20.5,39.8],[20.2,40.8],[19.5,41.8],[18.5,42.6],[17,43.4],[15.5,44.2],[14.4,45]]},{"id":"haemus","name":"Haemus (Balkan mountains)","kind":"mountain","note":"The range dividing Thrace from Moesia.","ring":[[22.3,43.6],[26.8,42.9],[26.8,42.5],[24,42.7],[22.2,43.1]]},{"id":"rhodope","name":"Succi pass & Rhodope","kind":"mountain","note":"The Via Militaris crossed the Succi pass between Serdica and Philippopolis, a famous choke point (Ammianus 21.10).","ring":[[23.4,42.65],[24.3,42.4],[25.5,41.9],[26,41.5],[25,41.2],[23.6,41.4],[23.3,42]]},{"id":"anatolia","name":"Anatolian plateau & Taurus","kind":"mountain","note":"A high plateau with bitter winters; the road south crosses the Taurus at the Cilician Gates.","ring":[[29.5,39.8],[31.5,40.5],[34.5,40.7],[37.5,40.2],[38.5,38.5],[37.5,37.6],[35.5,37.2],[33.5,36.6],[31.5,36.9],[30,37.5],[29.2,38.6]]},{"id":"lebanon","name":"Lebanon & Anti-Lebanon","kind":"mountain","note":"Snow lies on Mount Lebanon for much of the year — the name means \"white\".","ring":[[35.6,33.3],[36.4,34.6],[36.7,34.3],[36.2,33.4],[35.8,33.1]]},{"id":"atlas","name":"Atlas mountains","kind":"mountain","note":"The ranges of Mauretania and the Aurès, home of independent Moorish peoples.","ring":[[-9.5,30.6],[-5,32.3],[-3,33.2],[0,34.3],[3,35],[6.5,35.3],[8,35.1],[7,34.6],[4,34.4],[0,33.5],[-3.5,32.3],[-6,31],[-8.5,30.2]]},{"id":"pennines","name":"Pennines & the Wall country","kind":"mountain","note":"Bleak uplands of northern Britain; the Vindolanda tablets ask for warm socks and underpants.","ring":[[-2.8,53.5],[-1.8,53.5],[-1.9,55.2],[-2.8,55.2]]},{"id":"sahara","name":"Sahara & Libyan desert","kind":"desert","note":"Caravans crossed from oasis to oasis, travelling by night in summer.","ring":[[-10,29],[-2,31.5],[5,32.5],[9.5,32.8],[10.5,31.8],[13.5,31.5],[15.5,31.2],[17.5,30.8],[19.5,30.6],[20.5,31.3],[21.5,31.6],[24,31.3],[26,31],[29,30.6],[30.5,29.5],[30.9,27.5],[31.5,26],[32.4,25],[32.7,23],[33,15],[-10,15]]},{"id":"eastern_desert","name":"Eastern Desert, Sinai & Negev","kind":"desert","note":"Roads to the Red Sea ports ran between guarded wells (hydreumata); the Incense Road crossed the Negev.","ring":[[31.5,29.8],[32.3,30.2],[33.5,30.8],[34.4,31.1],[34.9,31.1],[35.3,30.9],[35,29.5],[34.5,28],[35.8,24],[36.5,22],[33.5,22],[33,24.5],[32.95,25.7],[32.85,26.3],[31.9,27.5],[31.4,28.5]]},{"id":"syrian_desert","name":"Syrian & Arabian desert","kind":"desert","note":"Crossed by caravans from Palmyra and by Arab tribes; deadly in high summer.","ring":[[36.4,31.5],[36.8,32.6],[37.6,33.6],[38.2,34.6],[38.6,35.9],[39.4,35.9],[40.4,35],[41.5,34],[42.8,33.2],[44.2,32],[46.5,30.2],[48,29.5],[47,24],[38,24],[35.8,28.5],[35.6,30],[35.9,31]]},{"id":"nile_delta","name":"Nile Delta","kind":"floodplain","note":"During the inundation the Delta became a sheet of water with towns standing like islands (Herodotus 2.97); people travelled by boat instead of on the roads.","ring":[[29.9,31.4],[32.4,31.3],[32.3,30.6],[31.3,29.9],[30.5,30.4]]}];
AWT.periods = [{"id":"500bc","label":"500 BC","title":"The Persian Empire & the Greek world","summary":"Darius I rules the Achaemenid Empire from the Aegean to the Indus, linked by the Royal Road. Greek and Phoenician city-states have colonised the Mediterranean and Black Sea coasts, Carthage dominates the western seas, and Rome is a young republic (traditionally founded 509 BC). The Ionian Revolt against Persia is about to break out (499 BC).","year":-500,"bordersMapped":[-550,-335],"regionLabels":[{"text":"Achaemenid Persian Empire","lat":36.2,"lng":42,"size":"lg"},{"text":"Hellas","lat":38.9,"lng":22},{"text":"Magna Graecia","lat":39.4,"lng":16.4},{"text":"Etruria","lat":43,"lng":11.6},{"text":"Carthaginian sphere","lat":34.6,"lng":8},{"text":"Egypt (Persian satrapy)","lat":27.5,"lng":31},{"text":"Scythians","lat":47.6,"lng":34},{"text":"Iberians & Celts","lat":40,"lng":-4},{"text":"Celts","lat":46.8,"lng":3},{"text":"Thrace","lat":42.2,"lng":25.2},{"text":"Libyan peoples","lat":29.5,"lng":18},{"text":"Kush","lat":19.5,"lng":32},{"text":"Illyrians","lat":43.6,"lng":18.4}]},{"id":"0ce","label":"0 CE","title":"The Roman Empire under Augustus","summary":"Around the turn of the era (there is no year zero — 1 BC is followed by AD 1) Augustus rules a Mediterranean that is, for the first time, under a single power. Roman roads and the grain fleets tie the provinces to Rome; Parthia rules Mesopotamia and Iran, and Nabataean caravans bring incense from Arabia to Gaza.","year":1,"bordersMapped":[-30,40],"regionLabels":[{"text":"Roman Empire","lat":44.3,"lng":19.5,"size":"lg"},{"text":"Parthian Empire","lat":34.8,"lng":46,"size":"lg"},{"text":"Egypt (Roman province)","lat":27.5,"lng":31},{"text":"Nabataean Kingdom","lat":29.6,"lng":36.8},{"text":"Judaea","lat":31.2,"lng":35.3},{"text":"Mauretania (client kingdom)","lat":34.3,"lng":-2.5},{"text":"Bosporan Kingdom","lat":45.6,"lng":37.6},{"text":"Gallia","lat":46.6,"lng":2.5},{"text":"Hispania","lat":40,"lng":-4},{"text":"Germania","lat":50.5,"lng":10},{"text":"Garamantes","lat":27.6,"lng":14.5},{"text":"Kingdom of Kush","lat":19.5,"lng":32},{"text":"Armenia","lat":40.6,"lng":42.6},{"text":"Pannonia (being conquered)","lat":46.4,"lng":17.6},{"text":"Dacians","lat":46,"lng":24.5}]},{"id":"300ce","label":"300 CE","title":"The Tetrarchy of Diocletian","summary":"After the 3rd-century crisis, Diocletian has split power among four emperors, each ruling from a frontier capital: Nicomedia, Mediolanum, Sirmium and Thessalonica, and Augusta Treverorum. The frontiers hold again from Hadrian's Wall to the Euphrates, and the Peace of Nisibis (299) has pushed Rome beyond the Tigris. Christianity is spreading fast; the Great Persecution will begin in 303, and Constantine will found Constantinople in 330.","year":300,"bordersMapped":[285,330],"regionLabels":[{"text":"Caledonians & Picts","lat":56.8,"lng":-4},{"text":"Franks","lat":52.3,"lng":7.5},{"text":"Alamanni","lat":48.9,"lng":9.6},{"text":"Goths","lat":47.3,"lng":30},{"text":"Sarmatians","lat":46.6,"lng":20.6},{"text":"Moors","lat":33.5,"lng":-2},{"text":"Blemmyes & Nobatae","lat":22.7,"lng":33.3},{"text":"Arab tribes","lat":29,"lng":40}]},{"id":"500ad","label":"500 CE","title":"Successor kingdoms & the Eastern Roman Empire","summary":"The western empire has given way to Germanic kingdoms: Theoderic the Ostrogoth rules Italy from Ravenna, the Vandals hold Carthage, the Visigoths Toulouse and Spain. Emperor Anastasius I governs the East from Constantinople, fed by the Egyptian grain fleet, while the Sasanian Persians rule from Ctesiphon. Pilgrims travel the roads to Jerusalem.","year":500,"bordersMapped":[476,507],"regionLabels":[{"text":"Eastern Roman Empire","lat":39.2,"lng":33,"size":"lg"},{"text":"Sasanian Empire","lat":34.6,"lng":46.5,"size":"lg"},{"text":"Ostrogothic Kingdom","lat":43.4,"lng":12.6},{"text":"Visigothic Kingdom","lat":41,"lng":-3.5},{"text":"Vandal Kingdom","lat":34.9,"lng":8.8},{"text":"Burgundians","lat":46.4,"lng":5.4},{"text":"Franks (Clovis)","lat":48.8,"lng":2.5},{"text":"Moorish kingdoms","lat":33.8,"lng":-3.5},{"text":"Ghassanids","lat":32.3,"lng":37.5},{"text":"Lakhmids","lat":31.3,"lng":43.6},{"text":"Gepids","lat":46.6,"lng":21},{"text":"Persarmenia","lat":39.6,"lng":45.4},{"text":"Lazica","lat":42.6,"lng":42.6},{"text":"Nubian kingdoms","lat":20,"lng":32}]},{"id":"565ce","label":"565 CE","title":"The age of Justinian — only the Eastern Romans remain","summary":"The western empire is long gone, but Justinian (died 14 November 565) has won back Africa from the Vandals (533–534), Italy from the Ostrogoths (535–554) and a strip of southern Spain, making the Mediterranean briefly a Roman lake again. Hagia Sophia (537) crowns Constantinople, though plague (541) has ravaged the empire. Frankish kings rule Gaul, the Visigoths rule Spain from Toledo, and Khosrow I rules Persia. The Lombards wait in Pannonia; they will invade Italy in 568.","year":565,"bordersMapped":[554,568],"regionLabels":[{"text":"Anglo-Saxons & Britons","lat":52.6,"lng":-1.5},{"text":"Bretons","lat":48.1,"lng":-3},{"text":"Avars","lat":46.3,"lng":29},{"text":"Slavs","lat":47,"lng":26.5},{"text":"Basques & Cantabrians","lat":43.1,"lng":-3.6},{"text":"Arab tribes","lat":28.5,"lng":40},{"text":"Saxons","lat":53,"lng":10}]}];
